import meta from './photos.json'

/** One photo in the Photos app. Generated by tools/add-photos.py — see its header. */
export interface Photo {
  name: string
  src: string
  thumb: string
  date: Date
  width: number
  height: number
  caption: string
}

const full = import.meta.glob<string>('../assets/photos/*.webp', { eager: true, import: 'default' })
const thumbs = import.meta.glob<string>('../assets/photos/thumbs/*.webp', { eager: true, import: 'default' })

/** Oldest first, like the Photos library grid (newest at the bottom). */
export const photos: Photo[] = meta
  .map((p) => ({
    ...p,
    src: full[`../assets/photos/${p.name}.webp`],
    thumb: thumbs[`../assets/photos/thumbs/${p.name}.webp`],
    date: new Date(p.date),
  }))
  .filter((p) => p.src && p.thumb)
